create procedure [dbo].[ETL_DimensionPart_Kassa]
(
	@Type nvarchar(4000) = null
	,@ParamList nvarchar(4000) = null	
	,@ParentEventID int = null
)
as
--
-- Standardvariabler
--
declare @ProcName sysname, @TranCount int, @EventIDStack varbinary(max)
set @ProcName = app.GetObjectFullName(@@procid)
set @TranCount = @@trancount


begin try
	--------------------------------------------------------------------------
	-- Start
	--------------------------------------------------------------------------
	exec app.LogEventStart @ParentEventID = @ParentEventID, @EventIDStack = @EventIDStack output, @EventObject = @ProcName
			,@EventTitle = 'ETL Dimension Part: Kassa'
			,@Description = null

	--------------------------------------------------------------------------
	-- Dimension part: Kassa
	-- Template: LoadCodePart.sql
	--------------------------------------------------------------------------
	select 
		Code = src.RNo
		,Name = isnull(src.Nm, cast(src.RNo as varchar(80)))		
		,DisplayName = cast(src.RNo as varchar(80)) + isnull(' ' + src.Nm, '')
		,DisabledAt = CONVERT (datetime,convert(char(8),nullif(src.REndDt, 0)))
		,IsDisabled = (CONVERT([bit],case when nullif(src.REndDt, 0)<=((datepart(year,getdate())*(10000)+datepart(month,getdate())*(100))+datepart(day,getdate())) then (1) else (0) end))
		,ParentCode = nullif(src.MainR3, src.RNo)
	into #DimensionPart14
	from
		[INSIKT_KUND_SA].visma.R3 src
	where
		SA_SourceSystemID = 1
	
	exec [app].[SyncDimensionPart]
		@DimensionPartTypeID = 14
		,@InputTable = '#DimensionPart14'
		,@ChangesBy = @ProcName	
		,@ParentEventID = @EventIDStack
	
	--
	-- Sätt parent ID för MainRX-hierarki
	--
	update dp set
		[ParentKassaID] = parentDp.[KassaID]
	from
		[dw].[base_Kassa] dp
			left join [dw].[base_Kassa] parentDp on
				parentDp.Code = dp.ParentCode
	where
		isnull(dp.[ParentKassaID], 0 ) <> isnull(parentDp.[KassaID], 0)
	
	update dp set
		dp.IsParent = iif(l.[KassaID] is null, 1, 0)
	from
		[dw].[base_Kassa] dp
			left join 
			(
				select
					l.[KassaID]
				from
					[dw].[base_Kassa] l
				where
					not exists(select 1 from [dw].[base_Kassa] c where c.[ParentKassaID] = l.[KassaID])
			) l on l.[KassaID] = dp.[KassaID]
	where
		dp.IsParent <> iif(l.[KassaID] is null, 1, 0)
	--------------------------------------------------------------------------
	

	exec app.LogEventStop @EventIDStack = @EventIDStack out
	--------------------------------------------------------------------------
	-- Stop
	--------------------------------------------------------------------------
end try
begin catch	
	--
	-- Roll back any transactions and log errors
	--
	if @TranCount = 0 and @@trancount > 0 rollback tran
	exec app.HandleProcError @EventIDStack out, @ParentEventID, @ProcName
	exec app.ReThrowError
end catch

